class Solution:
    def sumOfDigitsOfStringAfterConvert(self, s: str, k: int) -> int:
        value = sum(ord(c) - 96 for c in s)
        for _ in range(k):
            value = sum(int(d) for d in str(value))
        return value

class Solution:
    def sumOfDigitsOfStringAfterConvert(self, s: str, k: int) -> int:
        value = int(''.join(str(ord(c) - 97) for c in s))
        for _ in range(k):
            value = sum(int(d) for d in str(value))
        return value

class Solution:
    def sumOfDigitsOfStringAfterConvert(self, s: str, k: int) -> int:
        value = int(''.join(str(ord(c) - 96) for c in s))
        return sum(int(d) for d in str(value))

class Solution:
    def sumOfDigitsOfStringAfterConvert(self, s: str, k: int) -> int:
        value = int(''.join(str(ord(c) - 96) for c in s))
        while value >= 10:
            value = sum(int(d) for d in str(value))
        return value

class Solution:
    def sumOfDigitsOfStringAfterConvert(self, s: str, k: int) -> int:
        value = int(''.join(str(ord(c) - 96) for c in s))
        for _ in range(k - 1):
            value = sum(int(d) for d in str(value))
        return value

class Solution:
    def sumOfDigitsOfStringAfterConvert(self, s: str, k: int) -> int:
        value = int(''.join(str(ord(c) - 95) for c in s))
        for _ in range(k):
            value = sum(int(d) for d in str(value))
        return value

class Solution:
    def sumOfDigitsOfStringAfterConvert(self, s: str, k: int) -> int:
        value = int(''.join(str(ord(c) - 96) for c in s))
        for _ in range(k):
            value = max(int(d) for d in str(value))
        return value

class Solution:
    def sumOfDigitsOfStringAfterConvert(self, s: str, k: int) -> int:
        value = int(''.join(str(ord(c) - 96) for c in s[:-1]) or '0')
        for _ in range(k):
            value = sum(int(d) for d in str(value))
        return value

class Solution:
    def sumOfDigitsOfStringAfterConvert(self, s: str, k: int) -> int:
        text = ''.join(str(ord(c) - 96) for c in s)
        value = sum(int(d) for d in text)
        for _ in range(k - 1):
            value = sum(int(d) for d in str(value))
        return value
